def evaluate(current_reputation, observation, my_history, round_num):
    return 1.0 if observation['action'] == 'cooperate' else -1.0

def decide(recipient_reputation, round_num, my_history):
    if len(my_history) == 0:
        return True
    last = my_history[-1]['partner_action']
    if last == 'defect':
        if len(my_history) < 2 or my_history[-2]['partner_action'] == 'defect':
            return False
    return True

